  { auto _e = TARGET_POSITION_Z(); _o->TARGET_POSITION_Z = _e; }
  { auto _e = TARGET_VELOCITY_X(); _o->TARGET_VELOCITY_X = _e; }
  { auto _e = TARGET_VELOCITY_Y(); _o->TARGET_VELOCITY_Y = _e; }
  { auto _e = TARGET_VELOCITY_Z(); _o->TARGET_VELOCITY_Z = _e; }
  { auto _e = MISS_DISTANCE(); _o->MISS_DISTANCE = _e; }
  { auto _e = SEEKER(); if (_e) _o->SEEKER = _e->str(); }
  { auto _e = MOTOR(); if (_e) _o->MOTOR = _e->str(); }
  { auto _e = GUIDANCE_CMD(); if (_e) _o->GUIDANCE_CMD = _e->str(); }
  { auto _e = PHASE(); _o->PHASE = _e; }
